package cn.zhuatech.siem.deep;import cn.zhuatech.siem.common.ApiResponse;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/siem-ops") public class DeepDomainController{private final DeepDomainService s;public DeepDomainController(DeepDomainService s){this.s=s;}@GetMapping("/dashboard")ApiResponse<?> dashboard(@RequestParam String organizationCode){return ApiResponse.ok(s.dashboard(organizationCode));}@PostMapping("/sources")ApiResponse<?> source(@Valid @RequestBody DeepDomainService.SourceRequest r){return ApiResponse.ok(s.source(r));}@PostMapping("/sources/{id}/events")ApiResponse<?> ingest(@PathVariable Long id,@Valid @RequestBody DeepDomainService.EventRequest r){return ApiResponse.ok(s.ingest(id,r));}@PostMapping("/incidents/{id}/assign")ApiResponse<?> assign(@PathVariable Long id,@Valid @RequestBody DeepDomainService.AssignRequest r){return ApiResponse.ok(s.assign(id,r));}@PostMapping("/incidents/{id}/investigate")ApiResponse<?> investigate(@PathVariable Long id,@Valid @RequestBody DeepDomainService.InvestigationRequest r){return ApiResponse.ok(s.investigate(id,r));}@PostMapping("/incidents/{id}/respond")ApiResponse<?> respond(@PathVariable Long id,@Valid @RequestBody DeepDomainService.ResponseRequest r){return ApiResponse.ok(s.respond(id,r));}@PostMapping("/incidents/{id}/recover")ApiResponse<?> recover(@PathVariable Long id){return ApiResponse.ok(s.recover(id));}}
